-- Reconciled from production (project dqgrrafuoxaorvyrcuuh) on 2026-08-11 — this migration was applied directly to Supabase and had no local file until now.

create or replace function public.onboard_tenant(p_auth_id uuid, p_firm_name text, p_firm_slug text, p_owner_full_name text, p_branch_name text default 'Main Branch', p_branch_code text default 'MAIN', p_branch_address text default '', p_branch_phone text default '', p_plan_code text default 'trial-6mo', p_trial_months integer default 6) returns table (organization_id uuid, branch_id text, subscription_id uuid) language plpgsql security definer set search_path = public as $$ declare v_org_id uuid; v_branch_id text; v_plan_id uuid; v_sub_id uuid; begin if p_auth_id is null then raise exception 'onboard_tenant: p_auth_id is required'; end if; if not exists (select 1 from auth.users where id = p_auth_id) then raise exception 'onboard_tenant: auth.users row % does not exist', p_auth_id; end if; if exists (select 1 from public.user_profiles where auth_id = p_auth_id) then raise exception 'onboard_tenant: user % already has a profile', p_auth_id; end if; if trim(p_firm_name) = '' or trim(p_firm_slug) = '' then raise exception 'onboard_tenant: firm name and slug are required'; end if; select id into v_plan_id from public.platform_plans where code = p_plan_code and is_active; if v_plan_id is null then raise exception 'onboard_tenant: no active plan with code %', p_plan_code; end if; insert into public.organizations (slug, name, license_type, is_active, data) values (p_firm_slug, p_firm_name, 'trial', true, '{}'::jsonb) returning id into v_org_id; v_branch_id := 'br_' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12); insert into public.branches (id, firm_id, name, code, address, phone, manager_name, active, is_default, branch_type) values (v_branch_id, v_org_id, p_branch_name, p_branch_code, p_branch_address, p_branch_phone, p_owner_full_name, true, true, 'main'); insert into public.user_profiles (id, auth_id, firm_id, branch_id, full_name, status, active, is_super_owner, role, data, permissions) values (gen_random_uuid(), p_auth_id, v_org_id, v_branch_id, p_owner_full_name, 'active', true, false, 'Owner', '{}'::jsonb, '{}'::jsonb); insert into public.user_roles (user_id, role) values (p_auth_id, 'owner'::public.app_role) on conflict (user_id, role) do nothing; insert into public.organization_subscriptions (organization_id, plan_id, status, trial_started_at, trial_ends_at) values (v_org_id, v_plan_id, 'trial', now(), now() + make_interval(months => p_trial_months)) returning id into v_sub_id; perform public.apply_plan_entitlements(v_org_id, v_plan_id, 'Initial tenant onboarding'); insert into public.subscription_history (organization_id, subscription_id, action, after_value, actor_id, reason) values (v_org_id, v_sub_id, 'trial_started', jsonb_build_object('plan_code', p_plan_code, 'trial_months', p_trial_months), p_auth_id, 'Initial tenant onboarding'); return query select v_org_id, v_branch_id, v_sub_id; end; $$; create or replace function public.export_entitlement_enabled() returns boolean language sql stable security definer set search_path = public as $$ select public.organization_feature_enabled('export'); $$; revoke all on function public.export_entitlement_enabled() from public, anon; grant execute on function public.export_entitlement_enabled() to authenticated, service_role;
